import CareScale from './CareScale';
import '../styles/PlantItem.css';

function PlantItem({ id, cover, name, water, light }) {
  return (
    <article className="lmj-plant-item" data-plant-id={id}>
      <div className="plant-image-wrapper">
        <img
          className="lmj-plant-item-cover"
          src={cover}
          alt={`${name} cover`}
          loading="lazy"
        />
        <span className="plant-badge">plant girl era</span>
        <button
          type="button"
          className="plant-favorite"
          aria-label={`Ajouter ${name} aux favoris`}
          onClick={() => window.alert(`${name} ♡`)}
        >
          ♡
        </button>
      </div>

      <div className="plant-card-content">
        <p className="plant-category">BOTANICAL LOVE</p>
        <h3>{name}</h3>

        <div className="plant-care">
          <CareScale careType="light" scaleValue={light} />
          <CareScale careType="water" scaleValue={water} />
        </div>

        <div className="plant-card-footer">
          <span className="plant-price">À partir de 89 DH</span>
          <button
            type="button"
            className="plant-add-button"
            aria-label={`Sélectionner ${name}`}
            onClick={() => window.alert(`${name} ajouté à ta sélection ♡`)}
          >
            +
          </button>
        </div>
      </div>
    </article>
  );
}

export default PlantItem;
